function response(body,status=200,extra={}) { return new Response(body,{status,headers:{...baseHeaders,...extra}}); }
function page(title,body,status=200) {return response('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+escape(title)+' &middot; Speak I Hear</title>'+STYLE+'<header><span>Speak I Hear &middot; His Love Story</span><nav aria-label="Main navigation"><a href="/index.html">Main Menu</a> &middot; <a href="/testimonies">Our Shared Journey</a></nav></header><main>'+body+'</main></html>',status,{'Content-Type':'text/html; charset=utf-8'});}
function prompt(slug,error='',status=200) {return page(RECORDS[slug].title,'<h1>'+escape(RECORDS[slug].title)+'</h1><p>Enter your family password to read this part of His Love Story and see its photos, videos, and documents.</p>'+(error?'<p role="alert">'+escape(error)+'</p>':'')+'<form method="post"><p><label for="password">Password</label><br><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="256" style="font-size:20px;padding:10px;max-width:100%"></p><button class="next" type="submit">Enter</button></form><p><a href="/menu">Main Menu</a></p>',status);}
async function allowed(request,env,slug) {
 const cookies=request.headers.get('Cookie')||'';
 const token=cookies.split(';').map(s=>s.trim()).find(s=>s.startsWith(cookieName(slug)+'='))?.split('=')[1];
 if(!token||!/^[a-f0-9]{64}$/.test(token))return false;
 const obj=await env.FILES.get('_system/sessions/'+await hash(token));
 if(!obj)return false;
 const session=await obj.json();return session.slug===slug&&session.expires>Date.now();
}
async function attempt(request,env,slug) {
 const window=Math.floor(Date.now()/900000);
 const id=await hash((request.headers.get('CF-Connecting-IP')||'unknown')+'|'+slug);
 const key='_system/attempts/'+window+'/'+id;
 for(let i=0;i<5;i++) {
  const obj=await env.FILES.get(key);const n=obj?Number(await obj.text()):0;
  if(n>=10)return false;
  const result=await env.FILES.put(key,String(n+1),{onlyIf:obj?{etagMatches:obj.etag}:{etagDoesNotMatch:'*'}});
  if(result)return true;
 }
 return false;
}
async function listing(env,slug) {
 let out='';
 for(const kind of ['videos','photos','documents']) {
  const prefix=slug+'/'+kind+'/'; const files=await env.FILES.list({prefix,limit:200});
  if(!files.objects.length)continue;
  out+='<h2>'+({videos:'Videos',photos:'Photos',documents:'Documents'}[kind])+'</h2>';
  for(const obj of files.objects) {
   if(obj.key.endsWith('/'))continue;
   const name=obj.key.slice(prefix.length),href='/files/'+obj.key.split('/').map(encodeURIComponent).join('/');
   if(kind==='photos'&&/\.(jpg|jpeg|png|webp|gif)$/i.test(name))out+='<figure style="margin:24px 0"><img loading="lazy" style="max-width:100%;height:auto" src="'+href+'" alt="'+escape(name)+'"><figcaption>'+escape(name)+'</figcaption></figure>';
   else if(kind==='videos'&&/\.(mp4|webm|mov)$/i.test(name))out+='<p>'+escape(name)+'</p><video controls preload="metadata" style="width:100%" src="'+href+'">Your browser cannot play this recording.</video>';
   out+='<p><a href="'+href+'">Open or download '+escape(name)+'</a></p>';
   const subject='A memory about '+RECORDS[slug].title+' / '+name;
   const message='Sam,\n\nCollection: '+RECORDS[slug].title+'\nFile: '+name+'\n\nMy memory, identification, or correction:\n\nMy name:\n\nPlease contact me before adding my words or name to the website.\n';
   const memoryLink='mailto:sam.thomas@speakihear.org?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);
   out+='<p><a href="'+escape(memoryLink)+'">Send Sam a memory about this</a></p>';
  }
  if(files.truncated)out+='<p>More files are stored in this collection; additional pages will be added as it grows.</p>';
 }
 return out;
}
export default {async fetch(request,env) {
 if(new URL(request.url).pathname === "/assets/quiet-entrance.jpg") return new Response(request.method === "HEAD" ? null : Uint8Array.from(atob(QUIET_LANDSCAPE), c => c.charCodeAt(0)), {headers:{"Content-Type":"image/jpeg","Cache-Control":"public, max-age=86400"}});
 try {
 const url=new URL(request.url); let path;
 try {path=decodeURIComponent(url.pathname);}catch{return response('Invalid address',400);}
 if(path==='/assets/thanksgiving-autumn-farm-small.jpg' && ['GET','HEAD'].includes(request.method)) return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(""),c=>c.charCodeAt(0)),{headers:{...baseHeaders,'Content-Type':'image/jpeg','Cache-Control':'public, max-age=86400'}});
 if(path==='/assets/heartbeat-of-heaven-v2.jpg' && ['GET','HEAD'].includes(request.method)) return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(""),c=>c.charCodeAt(0)),{status:200,headers:{...baseHeaders,'Content-Type':'image/jpeg','Cache-Control':'public, max-age=86400'}});
 if(path==='/assets/glset-identity-v3.jpg' && ['GET','HEAD'].includes(request.method)) return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(""),c=>c.charCodeAt(0)),{status:200,headers:{...baseHeaders,'Content-Type':'image/jpeg','Cache-Control':'public, max-age=86400'}});
 if(['GET','HEAD'].includes(request.method)&&path==='/sitemap.xml'){
 const pages=[...Object.keys(PUBLIC_PAGES).filter(p=>!['/index.html','/entrance.html'].includes(p)),'/','/testimonies',...Object.keys(PAGES).filter(k=>!['welcome','collection'].includes(k)&&!Object.hasOwn(RECORDS,k)).map(k=>'/'+k)];
 const xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+[...new Set(pages)].map(p=>'<url><loc>https://speakihear.org'+p+'</loc></url>').join('')+'</urlset>';
 return response(request.method==='HEAD'?null:xml,200,{'Content-Type':'application/xml; charset=utf-8'});
 }
 if(['GET','HEAD'].includes(request.method)&&path==='/robots.txt')return response(request.method==='HEAD'?null:'User-agent: *\nAllow: /\nSitemap: https://speakihear.org/sitemap.xml\n',200,{'Content-Type':'text/plain; charset=utf-8'});
 if(['GET','HEAD'].includes(request.method)) {
  const publicPath = ['/', '/menu'].includes(path) ? '/index.html' : path;
  if(Object.hasOwn(PUBLIC_PAGES,publicPath))return response(request.method==='HEAD'?null:PUBLIC_PAGES[publicPath],200,{'Content-Type':'text/html; charset=utf-8'});
  if(Object.hasOwn(PUBLIC_FILES,publicPath)) {
   if(!env.FILES)return response('Temporarily unavailable',503);
   const file=PUBLIC_FILES[publicPath];let obj=await env.FILES.get(file.key,{range:request.headers});
   if(!obj){
    const original=await fetch('https://sambolusthomas.github.io'+publicPath);
    if(!original.ok)return response('File is being prepared',503);
    await env.FILES.put(file.key,original.body,{httpMetadata:{contentType:file.type}});
    obj=await env.FILES.get(file.key,{range:request.headers});
    if(!obj)return response('File is being prepared',503);
   }
   const headers={...baseHeaders,'Content-Type':file.type,'Accept-Ranges':'bytes','ETag':obj.httpEtag};
   if(publicPath==='/assets/speakihear-cosmic-intro.png'||publicPath==='/assets/speakihear-entry.js')headers['Cache-Control']='public, max-age=31536000, immutable';
   let status=200;
   if(obj.range&&'offset' in obj.range&&'length' in obj.range){status=206;headers['Content-Range']=`bytes ${obj.range.offset}-${obj.range.offset+obj.range.length-1}/${obj.size}`;headers['Content-Length']=String(obj.range.length);}else headers['Content-Length']=String(obj.size);
   return new Response(request.method==='HEAD'?null:obj.body,{status,headers});
  }
 }
 if(path==='/testimonies')path='/collection';
 if(path==='/favicon.ico')return response(null,204);
 if(!['GET','HEAD','POST'].includes(request.method))return response('Method not allowed',405,{'Allow':'GET, HEAD, POST'});
 const isFile=path.startsWith('/files/'); const parts=path.split('/');
 const slug=isFile?parts[2]:(path.replace(/^\/+|\/+$/g,'')||'menu');
 if(!Object.hasOwn(RECORDS,slug)&&!(!isFile&&Object.hasOwn(PAGES,slug)))return page('Not found','<h1>Page not found</h1><p><a href="/menu">Main Menu</a></p>',404);
 if((isFile||Object.hasOwn(RECORDS,slug))&&!env.FILES)return page('Preparing this collection','<h1>This collection is being prepared</h1><p>Please check back shortly.</p>',503);
 if(isFile) {
  if(request.method==='POST')return response('Method not allowed',405);
  if(!await allowed(request,env,slug))return prompt(slug);
  if(!['photos','videos','documents'].includes(parts[3])||parts.length<5||parts.some(p=>p==='.'||p==='..'||p.includes('\\')))return response('Not found',404);
  const key=parts.slice(2).join('/');
  const obj=await env.FILES.get(key,{range:request.headers});if(!obj)return response('File not found',404);
  const headers=new Headers(baseHeaders);obj.writeHttpMetadata(headers);
  headers.set('Cache-Control','private, no-store');headers.set('X-Content-Type-Options','nosniff');headers.set('Accept-Ranges','bytes');headers.set('ETag',obj.httpEtag);
  if(parts[3]==='documents'||!/^image\/(jpeg|png|webp|gif)$|^video\/(mp4|webm|quicktime)$/.test(headers.get('Content-Type')||''))headers.set('Content-Disposition',"attachment; filename*=UTF-8''"+encodeURIComponent(parts.at(-1)));
  let status=200;
  if(obj.range&&'offset' in obj.range&&'length' in obj.range){status=206;headers.set('Content-Range',`bytes ${obj.range.offset}-${obj.range.offset+obj.range.length-1}/${obj.size}`);headers.set('Content-Length',String(obj.range.length));}
  else headers.set('Content-Length',String(obj.size));
  return new Response(request.method==='HEAD'?null:obj.body,{status,headers});
 }
 if(request.method==='POST') {
  if(!Object.hasOwn(RECORDS,slug))return response('Not found',404);
  if(request.headers.get('Origin')!==url.origin && request.headers.get('Sec-Fetch-Site')!=='same-origin')return response('Forbidden',403);
  if(!request.headers.get('Content-Type')?.startsWith('application/x-www-form-urlencoded'))return response('Unsupported form',415);
  const reader=request.body?.getReader();if(!reader)return response('Bad request',400);
  let raw='',size=0;const decoder=new TextDecoder();
  while(true){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>4096){await reader.cancel();return response('Form too large',413);}raw+=decoder.decode(value,{stream:true});}raw+=decoder.decode();
  if(!await attempt(request,env,slug))return prompt(slug,'Too many attempts. Please wait 15 minutes before trying again.',429);
  const password=new URLSearchParams(raw).get('password')||'',record=RECORDS[slug];
  const key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);
  const digest=hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:Uint8Array.from(record.salt.match(/../g),h=>parseInt(h,16)),iterations:100000,hash:'SHA-256'},key,256));
  let mismatch=0;for(let i=0;i<64;i++)mismatch|=digest.charCodeAt(i)^record.hash.charCodeAt(i);
  if(mismatch)return prompt(slug,'That password was not recognized. Please try again.',403);
  const token=hex(crypto.getRandomValues(new Uint8Array(32)));
  await env.FILES.put('_system/sessions/'+await hash(token),JSON.stringify({slug,expires:Date.now()+3600000}));
  return response(null,303,{'Location':'/'+slug,'Set-Cookie':cookieName(slug)+'='+token+'; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=3600'});
 }
 if(Object.hasOwn(RECORDS,slug)&&!await allowed(request,env,slug))return prompt(slug);
 let body=PAGES[slug];
 if(Object.hasOwn(RECORDS,slug))body=body.replace('<nav class="reading"',await listing(env,slug)+'<nav class="reading"');
 return page(RECORDS[slug]?.title||'His Love Story',body);
 }catch{return page('Please try again','<h1>Temporarily unavailable</h1><p>Please try again shortly.</p>',503);}
}};

// Our Shared Journey introduction and chronicle. Preserve the existing private recollection invitation.
{
 const previousCollection = PAGES.collection;
 const recollection = previousCollection.match(/<h2[^>]*>Share a recollection<\/h2>[\s\S]*?<\/p>/)?.[0] || "";
 PAGES.collection = "<span class=\"eyebrow\">His Love Story</span><h1>Our Shared Journey</h1>\n<p>My parents named me Samuel. They knew God. They may not have known everything about society or the world, but they knew what mattered most: relationship with family, and first and foremost, relationship with a Living God.</p>\n<p>When I was about eight, a preacher related to our family came to visit. I remember thinking the world might end that very night. That was more than sixty years ago. Even then, very young, I began a relationship with the Living God. I didn’t understand what I had.</p>\n<p>As the years passed, that relationship faded. I went down roads I knew I should not have taken. I didn’t just wander down them—I ran.</p>\n<p>But when I thought the road had reached a dead end, I found an old Friend waiting there. It was as though He had been waiting every evening for me to come home.</p>\n<p>These pages tell some of that journey. There are failures here, lessons learned, and people whose love and encouragement helped me along the way. Our lives became woven together through a Love greater than we understood. You may be one of those people. If you are, I hope you recognize that you are part of this story.</p>\n<p>Now I long to be “clothed upon” with my new body and dwell with my Savior. I look forward to His coming. Until then, I want to share what I have known of His love and invite someone else to walk beside me toward the King.</p>\n<p>Along this journey, God placed pastors in my life who helped unlock another part of the pathway. Each place holds memories of people who walked beside me, encouraged me, and helped me know His love more deeply.</p>\n<p>To enter the memories from each place, remember the pastor who served there. <strong>His last name is the key.</strong></p>\n<p>Read the story. Visit the memories. Perhaps you will find something of your own journey here—or share a testimony of your own. You are welcome to walk with me into a Love so immense it defies words.</p><p>—Samuel</p>\n<section aria-labelledby=\"chronicle\"><h2 id=\"chronicle\">The journey through these places</h2><p>Follow the chronicle from Ponca City to Lewisville, Sherman, and Perkins, or return to a place you remember.</p><ol class=\"menu-list\"><li><a href=\"/ponca-city\">Ponca City</a></li><li><a href=\"/christ-church-lewisville\">Christ Church Lewisville</a></li><li><a href=\"/harvest-time-sherman\">Harvest Time Sherman</a></li><li><a href=\"/freedom-perkins\">Freedom Perkins</a></li></ol></section>\n<section aria-labelledby=\"helps\"><h2 id=\"helps\">Writings for the Journey</h2><p>Alongside these memories, this will be a place for standalone writings—reflections and helps to encourage fellow travellers on their way to see the King.</p><p>More writings will be added as they are ready.</p><p><a href=\"/index.html\">Explore the writings already available →</a></p></section>" + recollection + "<nav class=\"reading\" aria-label=\"Reading navigation\"><a href=\"/index.html\">Main Menu</a><a class=\"next\" href=\"/ponca-city\">Next: Ponca City →</a></nav>";
 PAGES.welcome = PAGES.collection;
}


PAGES["knowing-him"] = "<article><span class=\"eyebrow\">Writings for the Journey</span><h1>Knowing Him</h1><p><em>Where Do I Begin?</em></p>\n<p>Suppose for a moment that the Creator of the universe is real. Not merely an idea, a religious tradition, or someone who lived long ago, but a living God who knows you and desires that you know Him.</p>\n<p>Think about that for a moment. The One who brought the universe into existence wants a personal relationship with you.</p>\n<p>What could He possibly want from me? How do I approach Someone so far beyond anything I have ever known? How do I begin a conversation with Someone who exists beyond the limitations of time and space?</p>\n<p>Scripture gives us a remarkably simple place to begin.</p>\n<p>Hebrews 11:6 tells us that whoever comes to God must first believe that He exists and that He rewards those who diligently seek Him.</p>\n<p>There is our beginning. We must believe that He is, that He is alive, and that He responds to those who seek Him.</p>\n<p>Now suppose we have taken that first step. We believe He exists. We want to know Him. Where do we go from here?</p>\n<p>There is a delightful old song from <em>The King and I</em> called <em>Getting to Know You</em>. Its familiar opening, “Getting to know you, getting to know all about you,” expresses something wonderfully simple about relationships.</p>\n<p>Think about how we become acquainted with another person. We spend time together. We talk, we listen, and we begin to understand what matters to them. We discover what brings them joy, what troubles them, what they love, and what they dislike.</p>\n<p>As the relationship grows, something remarkable begins to happen. We become familiar with their voice, their thoughts, and their ways. Eventually, we may know them so well that we can anticipate what would please them before they ever say a word.</p>\n<p>Could our relationship with God become that personal?</p>\n<p>Could we know Him well enough to recognize what pleases Him? Could we become so familiar with His ways that we recognize His voice among all the other voices competing for our attention?</p>\n<p>Jesus said something astonishing to His disciples:</p>\n<blockquote><p>“No longer do I call you servants ... but I have called you friends.” — <a href=\"https://www.biblegateway.com/passage/?search=John%2015%3A15&amp;version=ESV\">John 15:15</a></p></blockquote>\n<p>Imagine being called a friend by the Creator of the universe!</p>\n<p>There is, however, something we must understand. We live in a world governed by time, space, and the physical things we can see and touch. God is eternal. His perspective is not limited to the few years we spend on this earth.</p>\n<p>Scripture tells us:</p>\n<blockquote><p>“For the things that are seen are transient, but the things that are unseen are eternal.” — <a href=\"https://www.biblegateway.com/passage/?search=2%20Corinthians%204%3A18&amp;version=ESV\">2 Corinthians 4:18</a></p></blockquote>\n<p>How, then, can we begin to understand Someone who speaks from an eternal perspective when everything around us seems temporary?</p>\n<p>The answer is extraordinary in its simplicity.</p>\n<p><strong>He has already spoken to us in our own language.</strong></p>\n<p>He has given us His Word.</p>\n<p>Throughout Scripture, God reveals His character, His desires, His purposes, and His love. He allows us to see how He relates to humanity, how He responds to faith, how He deals with disobedience, and how faithfully He pursues those He loves.</p>\n<p>From the opening words of Genesis to the remarkable scene in Revelation 5, where the Lamb receives the scroll from the One seated upon the throne, we discover that God's purposes reach far beyond our understanding of time.</p>\n<p>We are encountering something eternal, expressed in language we can understand.</p>\n<p>Yet His Word does something even more wonderful. It introduces us to Someone.</p>\n<p>John begins his Gospel with these words:</p>\n<blockquote><p>“In the beginning was the Word, and the Word was with God, and the Word was God.” — <a href=\"https://www.biblegateway.com/passage/?search=John%201%3A1&amp;version=ESV\">John 1:1</a></p></blockquote>\n<p>Then John tells us that the Word became flesh and dwelt among us.</p>\n<p>Think about what that means.</p>\n<p>The eternal God, whom we cannot begin to comprehend in all His fullness, has made Himself known through Jesus Christ.</p>\n<p>If we want to discover what God is like, we can begin by looking at Jesus.</p>\n<p>We can listen to His words. We can watch how He treated people. We can discover what pleased Him, what grieved Him, what moved Him to compassion, and what He considered important.</p>\n<p>We can begin to understand His heart.</p>\n<p>Yet Jesus did not come merely to demonstrate how we should live. He came to restore the relationship with God that humanity had lost. He made the way for us to approach God, and He promised Holy Spirit to teach, guide, and help us.</p>\n<p>We are not left to discover God through our own strength or understanding.</p>\n<p>We can speak to Him. We can pray. We can read His Word, consider what He has said, and learn to recognize His character and His ways. As we grow in our relationship with Him, we can learn to distinguish His leading from our own desires and imagination, always testing what we believe we hear against Scripture.</p>\n<p>Jesus said:</p>\n<blockquote><p>“My sheep hear my voice, and I know them, and they follow me.” — <a href=\"https://www.biblegateway.com/passage/?search=John%2010%3A27&amp;version=ESV\">John 10:27</a></p></blockquote>\n<p>Notice something beautiful about those words. Jesus did not merely say that His sheep know about Him.</p>\n<p>He said that <strong>He knows them.</strong></p>\n<p>This relationship was never intended to be one-sided.</p>\n<p>Perhaps you have spent much of your life hearing about God. You may have attended church, listened to sermons, read the Bible, or learned the stories of Jesus. All of those things can be valuable, but knowing about someone is not the same as knowing that person.</p>\n<p>The Creator of the universe is not merely a subject to be studied. He is Someone to be known.</p>\n<p>And perhaps the best place to begin is with a simple conversation:</p>\n<p><em>Lord, I believe You are real. I believe You are alive. I believe You hear me, and I want to know You. I don't always understand how You speak, and I have so much to learn about You. Please teach me. Help me recognize Your voice, understand Your Word, and discover what pleases You.</em></p>\n<p>There is no need for impressive language. There is no need to pretend we understand things we do not.</p>\n<p>We simply begin.</p>\n<p>The remarkable thing about getting to know Jesus is that we are not beginning a relationship with Someone who has only just discovered us.</p>\n<p><strong>He already knows us. He has known us all along.</strong></p>\n<p>Perhaps it is time we began getting to know Him.</p></article>\n<nav class=\"reading\" aria-label=\"Reading navigation\"><a href=\"/index.html\">Main Menu</a><a class=\"next\" href=\"/testimonies#helps\">Next: Writings for the Journey →</a></nav>";
for (const entry of ["collection", "welcome"]) { PAGES[entry] = PAGES[entry].replace("<p>More writings will be added as they are ready.</p>", "<article><h3><a href=\"/knowing-him\">Knowing Him</a></h3><p><em>Where Do I Begin?</em></p><p><a href=\"/knowing-him\">Read Knowing Him →</a></p></article><p>More writings will be added as they are ready.</p>"); }

// Standalone writing and Scripture reading sections.
PAGES["the-immovable-object"] = "<article><span class=\"eyebrow\">Writings for the Journey</span><h1>The Immovable Object</h1><p><em>When Nothing Seems to Move</em></p>\n<p>Have you ever pushed against something with all your strength and watched absolutely nothing happen?</p>\n<p>You brace your feet. You lean forward. You put everything you have into the effort. Yet the object remains exactly where it was.</p>\n<p>After a while, you begin to wonder why you are trying.</p>\n<p>Sometimes our walk with God can feel that way. We pray. We read His Word. We try to obey what we understand. We return to Him with the same burden, and the circumstances before us seem unchanged.</p>\n<p>Lord, are You there? Do You hear me? Is any of this accomplishing anything?</p>\n<p>Think again about that immovable object. As you press against it, it exerts an equal and opposite force upon you. The absence of movement does not mean the absence of an interaction. Your muscles are working, even though the object has not moved.</p>\n<p>That picture helps me think about perseverance, though our relationship with God is more than a law of physics. We cannot measure His love by how hard we push, or make Him answer by applying enough pressure.</p>\n<p><strong>But we must not mistake the absence of visible movement for the absence of God.</strong></p>\n<p>In Isaiah, God assures His people that He is with them and will strengthen and help them. Their need for help does not put them beyond His reach. Neither does our weakness mean we have been forgotten.</p>\n<p>Paul understood something about a burden that remained. He asked the Lord repeatedly to remove an affliction. The answer he received was the assurance of Christ’s sufficient grace and power made perfect in weakness. The affliction had not simply disappeared, yet God had answered.</p>\n<p>Could there be something happening in us while we wait for something to happen around us?</p>\n<p>We may be learning patience. We may be discovering how little we can accomplish in our own strength. We may be learning to listen, to surrender our expectations, or to trust Him when we cannot explain what He is doing.</p>\n<p><strong>Perhaps the first thing God intends to move is something within me.</strong></p>\n<p>That does not make the effort unimportant. Paul tells believers to work out their salvation, and then reminds them that God is working within them toward His good purpose. Our obedience matters, and even our ability to obey depends upon His help.</p>\n<p>We keep coming to Him. We pray honestly. We consider His Word. We take the next faithful step He has given us. Sometimes that step is to keep working. Sometimes it is to wait, receive help, or let go of a direction we have chosen for ourselves. Perseverance includes listening.</p>\n<p>We do not have to pretend that every obstacle is an assignment from God. We can ask Him for wisdom about whether to continue, change direction, or rest.</p>\n<p>Our hope rests in the One who raised Jesus from the dead. At the end of his teaching about resurrection, Paul encourages believers to remain steadfast in the Lord’s work, knowing that their labor in Him has lasting value.</p>\n<p>We may not see that value today. We may not understand the timing. But the God we seek is living, present, and able to accomplish purposes beyond what we can presently see.</p>\n<p><em>Lord, when nothing seems to move, help me remember that You are here. Teach me to recognize Your work and follow Your direction. Give me strength to continue where You lead, humility to change course when You ask, and trust to rest in Your grace. Accomplish Your purposes in me as well as through me.</em></p>\n<p>The object before us may still look immovable.</p>\n<p><strong>We can bring even that to a God who has not gone away.</strong></p><section aria-labelledby=\"scriptures\"><h2 id=\"scriptures\">Read the Scriptures</h2><p>Take time to read these passages in their context. Let God’s Word guide your understanding as you consider these reflections.</p><ul><li><a href=\"https://www.biblegateway.com/passage/?search=Isaiah%2041%3A10&amp;version=ESV\">Isaiah 41:10</a> — God’s assurance of His presence, strength, and help.</li><li><a href=\"https://www.biblegateway.com/passage/?search=Philippians%202%3A12%E2%80%9313&amp;version=ESV\">Philippians 2:12–13</a> — Our obedience and God’s work within us.</li><li><a href=\"https://www.biblegateway.com/passage/?search=2%20Corinthians%2012%3A7%E2%80%9310&amp;version=ESV\">2 Corinthians 12:7–10</a> — Paul’s prayer, Christ’s sufficient grace, and strength in weakness.</li><li><a href=\"https://www.biblegateway.com/passage/?search=1%20Corinthians%2015%3A50%E2%80%9358&amp;version=ESV\">1 Corinthians 15:50–58</a> — The hope of resurrection and the lasting value of labor in the Lord.</li></ul></section></article><nav class=\"reading\" aria-label=\"Reading navigation\"><a href=\"/index.html\">Main Menu</a><a class=\"next\" href=\"/testimonies#helps\">Next: Writings for the Journey →</a></nav>";
PAGES["knowing-him"] = PAGES["knowing-him"].replace("</article>", "<section aria-labelledby=\"scriptures\"><h2 id=\"scriptures\">Read the Scriptures</h2><p>Take time to read these passages in their context. Let God’s Word guide your understanding as you consider these reflections.</p><ul><li><a href=\"https://www.biblegateway.com/passage/?search=Hebrews%2011%3A6&amp;version=ESV\">Hebrews 11:6</a> — Coming to God in faith and seeking Him.</li><li><a href=\"https://www.biblegateway.com/passage/?search=John%2015%3A12%E2%80%9317&amp;version=ESV\">John 15:12–17</a> — Jesus speaks of friendship, love, and obedience.</li><li><a href=\"https://www.biblegateway.com/passage/?search=2%20Corinthians%204%3A16%E2%80%9318&amp;version=ESV\">2 Corinthians 4:16–18</a> — Looking toward what is eternal.</li><li><a href=\"https://www.biblegateway.com/passage/?search=Genesis%201%3A1&amp;version=ESV\">Genesis 1:1</a> — The beginning of Scripture’s account of creation.</li><li><a href=\"https://www.biblegateway.com/passage/?search=Revelation%205%3A1%E2%80%9314&amp;version=ESV\">Revelation 5:1–14</a> — The Lamb and the scroll before God’s throne.</li><li><a href=\"https://www.biblegateway.com/passage/?search=John%201%3A1%E2%80%9318&amp;version=ESV\">John 1:1–18</a> — The Word who became flesh and made God known.</li><li><a href=\"https://www.biblegateway.com/passage/?search=John%2014%3A6%2C%2016%E2%80%9326&amp;version=ESV\">John 14:6, 16–26</a> — Coming to the Father through Jesus and the promised Helper.</li><li><a href=\"https://www.biblegateway.com/passage/?search=John%2010%3A27%E2%80%9330&amp;version=ESV\">John 10:27–30</a> — Jesus knows His sheep, and they hear and follow Him.</li></ul></section></article>").replace('href="/testimonies#helps">Next: Writings for the Journey →', 'href="/the-immovable-object">Next: The Immovable Object →');
for (const entry of ["collection", "welcome"]) { PAGES[entry] = PAGES[entry].replace("<p>More writings will be added as they are ready.</p>", "<article><h3><a href=\"/the-immovable-object\">The Immovable Object</a></h3><p><em>When Nothing Seems to Move</em></p><p><a href=\"/the-immovable-object\">Read The Immovable Object →</a></p></article><p>More writings will be added as they are ready.</p>"); }

// Approved short devotional: How to Study the Bible.
PAGES["how-to-study-the-bible"] = "<article><span class=\"eyebrow\">Writings for the Journey</span><h1>How to Study the Bible</h1><p><em>Let the Word Live Within You</em></p>\n<p>How do we begin to study the Bible?</p>\n<p>We can gather books, compare translations, learn the history, and examine the meaning of individual words. These things can help us. But before we begin, perhaps we should consider whom we are seeking.</p>\n<p>John opens his Gospel by introducing us to the Word. He tells us that the Word was with God, that the Word was God, and that the Word became flesh and dwelt among us.</p>\n<p>He is introducing us to Jesus.</p>\n<p>Think for a moment about what words accomplish. A thought can remain hidden within us until we express it. Then something another person could not see becomes something they can begin to understand.</p>\n<p>Even a brief announcement can set things in motion. “They’re off!” and suddenly the excitement of a horse race fills the air.</p>\n<p>Words can reveal, invite, comfort, correct, and call us to action. Jesus Himself connected our speech with what fills our hearts.</p>\n<p>Could that help us begin to appreciate John’s description of Jesus as the Word?</p>\n<p>The comparison can only take us so far. Jesus is eternal, personally present with the Father before creation. Yet through Him, the God we could never fully comprehend has made Himself known.</p>\n<p>In Jesus, we encounter His character, His holiness, His compassion, and His love. We see His purpose for our redemption expressed through a life among us, through the cross, and through the resurrection.</p>\n<p><strong>When we open the Scriptures, we are seeking to know this living God.</strong></p>\n<p>Jesus told people who searched the Scriptures that those very Scriptures testified about Him. Yet they were unwilling to come to Him for life.</p>\n<p>That gives me something to consider. I can become familiar with the words on the page and still resist the One to whom they point.</p>\n<p>So where do we begin?</p>\n<h2>Begin with a conversation</h2>\n<p>Before reading, speak to Him.</p>\n<p><em>Lord, I want to know You. Help me understand what I am reading. Show me what this passage reveals about You, and help me respond faithfully.</em></p>\n<p>We do not need impressive language. We need a willingness to listen and learn.</p>\n<p>After His resurrection, Jesus helped His disciples understand the Scriptures concerning Himself. We can ask Him for understanding, too.</p>\n<section aria-labelledby=\"scriptures\"><h2 id=\"scriptures\">Read the Scriptures</h2><ul>\n<li><a href=\"https://www.biblegateway.com/passage/?search=John+1%3A1-18&amp;version=ESV\">John 1:1–18</a> — The Word becomes flesh and makes God known.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=Luke+6%3A45&amp;version=ESV\">Luke 6:45</a> — Our speech expresses what fills our hearts.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=John+5%3A39-40&amp;version=ESV\">John 5:39–40</a> — The Scriptures testify about Jesus.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=Luke+24%3A27%2C44-45&amp;version=ESV\">Luke 24:27, 44–45</a> — Jesus opens His disciples’ understanding.</li></ul></section></article>\n<nav class=\"reading\" aria-label=\"Reading navigation\"><a href=\"/index.html\">Main Menu</a><a class=\"next\" href=\"/testimonies#helps\">Next: Writings for the Journey →</a></nav>";
PAGES["the-immovable-object"] = PAGES["the-immovable-object"].replace('href="/testimonies#helps">Next: Writings for the Journey →', 'href="/how-to-study-the-bible">Next: How to Study the Bible →');
for (const entry of ["collection", "welcome"]) { PAGES[entry] = PAGES[entry].replace("<p>More writings will be added as they are ready.</p>", "<article><h3><a href=\"/how-to-study-the-bible\">How to Study the Bible</a></h3><p><em>Let the Word Live Within You</em></p><p><a href=\"/how-to-study-the-bible\">Read How to Study the Bible →</a></p></article><p>More writings will be added as they are ready.</p>"); }

// Approved devotional: The Depth of His Word.
PAGES["the-depth-of-his-word"] = "<article><span class=\"eyebrow\">Writings for the Journey</span><h1>The Depth of His Word</h1><p><em>“In the Beginning God…”</em></p>\n<p>God speaks to us through His Word.</p>\n<p>If you are just beginning to know Him, you may wonder what that means. Do we hear a voice? Does an answer suddenly appear?</p>\n<p>We can begin by opening the Scriptures.</p>\n<p>Jesus said His words would never pass away. Think about that. We live among things that grow old, wear out, and disappear. Yet His words endure. They speak into our lives today while revealing purposes that reach beyond our lifetime.</p>\n<p>Perhaps that is a beginning to understanding what it means to say, “He speaks eternally.”</p>\n<p>As an engineer, I want to understand every word I read. But the first four words of the Bible stopped me:</p>\n<p><strong>“In the beginning God…”</strong></p>\n<p>The beginning of what? God was already there? Where? What was there before the beginning?</p>\n<p>I had barely opened the Book, and already I was beyond the limits of my understanding.</p>\n<p>Yet those words give me somewhere to stand. Before the things whose beginnings I can investigate, God is there. The account begins with Him.</p>\n<p>John takes us deeper. In the beginning was the Word, and the Word was with God, and the Word was God. Then he tells us that the Word became flesh.</p>\n<p>We meet Jesus.</p>\n<p>The written Scriptures bear witness to Him. Through them, we begin to discover the character and love of the One who knows what we cannot yet comprehend.</p>\n<p>We will have questions. Some passages may puzzle us for years. We can read carefully, consider the surrounding verses, and learn from others. We can also bring our questions to God.</p>\n<p>James tells us to ask Him for wisdom.</p>\n<p>That invitation amazes me. The God whose understanding exceeds mine welcomes me to ask for help.</p>\n<p>He may lead me back to the passage, help me notice something I overlooked, or teach me through another person. Understanding can grow slowly. I do not have to force an answer to every mystery before taking the next step with Him.</p>\n<p><strong>Try it. Open His Word. Read a little. Ask Him for wisdom.</strong></p>\n<p><em>Lord, I do not understand everything before me. But I want to know You. Help me understand what You have revealed, and give me the humility to keep learning.</em></p>\n<p>There is depth here enough for a lifetime.</p>\n<p>And we can begin today.</p>\n<section aria-labelledby=\"scriptures\"><h2 id=\"scriptures\">Read the Scriptures</h2><ul>\n<li><a href=\"https://www.biblegateway.com/passage/?search=Genesis+1%3A1-5&amp;version=ESV\">Genesis 1:1–5</a> — The account of creation begins with God.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=John+1%3A1-18&amp;version=ESV\">John 1:1–18</a> — The eternal Word becomes flesh.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=Matthew+24%3A35&amp;version=ESV\">Matthew 24:35</a> — Jesus declares that His words will not pass away.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=Isaiah+40%3A8&amp;version=ESV\">Isaiah 40:8</a> — God’s word endures forever.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=James+1%3A5&amp;version=ESV\">James 1:5</a> — Ask God for wisdom.</li>\n<li><a href=\"https://www.biblegateway.com/passage/?search=Psalm+119%3A18&amp;version=ESV\">Psalm 119:18</a> — A prayer for opened eyes to see what God has revealed.</li></ul></section></article>\n<nav class=\"reading\" aria-label=\"Reading navigation\"><a href=\"/index.html\">Main Menu</a><a class=\"next\" href=\"/testimonies#helps\">Next: Writings for the Journey →</a></nav>";
PAGES["how-to-study-the-bible"] = PAGES["how-to-study-the-bible"].replace('href="/testimonies#helps">Next: Writings for the Journey →', 'href="/the-depth-of-his-word">Next: The Depth of His Word →');
