// Speak I Hear: The Invitation and three reading paths.
{
const navigation = {"styles": "\n:root{--paper:#f7f3ec;--ink:#302b28;--muted:#6b6258}\nbody{margin:0;background:var(--paper);color:var(--ink)}\nheader.preview-header{position:static}\n.preview-menu{display:flex;flex-wrap:wrap;gap:10px 20px;align-items:center;padding:10px 0}\n.preview-menu a[aria-current=page]{text-decoration:underline;text-underline-offset:5px}\nmain.wrap{width:min(92%,950px);margin:0 auto;padding:24px 0 48px}\n.preview-intro{margin:0 auto 28px;text-align:center}\n.preview-intro h1{margin:.2em 0}\n.preview-intro p{margin:.4em 0 1em;color:var(--muted)}\n.path-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:22px 0 32px}\n.path-card{display:block;padding:18px;background:#fffaf3;border:1px solid #dfd4c7;border-radius:12px;text-decoration:none;color:var(--ink)}\n.path-card strong{display:block;font-size:1.16em;line-height:1.25;margin-bottom:5px}\n.path-card span{color:var(--muted)}\n.path-card:hover,.path-card:focus-visible{border-color:#846144;background:#fcf0df}\n.preview-list li{margin:.55em 0}\n.preview-back{margin-top:36px}\n@media(max-width:680px){.path-grid{grid-template-columns:1fr}.preview-menu{gap:8px 14px}}\n", "cards": "<nav class=\"path-grid\" aria-label=\"Explore the writings\"><a class=\"path-card\" href=\"/testimonies\"><strong>Our Shared Journey</strong><span>Living in His Kingdom</span></a><a class=\"path-card\" href=\"/the-greatest-love-story\"><strong>The Greatest Love Story</strong><span>Discovering His eternal purpose</span></a><a class=\"path-card\" href=\"/library\"><strong>The Library</strong><span>Studies, sermons, testimonies</span></a></nav>", "library": "<div class=\"preview-intro\"><h1>The Library</h1><p>Studies, sermons, testimonies</p></div>\n<section><h2>Studies and Scripture</h2><ul class=\"preview-list\">\n<li><a href=\"/how-to-study-the-bible\">How to Study the Bible</a></li>\n<li><a href=\"/the-depth-of-his-word\">The Depth of His Word</a></li>\n<li><a href=\"/writings/scripture-references.html\">Scripture References</a></li></ul></section>\n<section><h2>Teachings and testimonies</h2><ul class=\"preview-list\">\n<li><a href=\"/what-does-it-sound-like-when-god-speaks\">What Does It Sound Like When God Speaks?</a></li>\n<li><a href=\"/covet-or-content\">Covet or Content?</a></li>\n<li><a href=\"/he-calls-me-by-name\">He Calls Me by Name</a></li>\n<li><a href=\"/stop-changing-it\">Don’t Change It</a></li>\n<li><a href=\"/testimonies#all-writings\">Browse all writings</a></li></ul></section>"};

const house = PUBLIC_PAGES['/index.html'];
const nav = '<nav aria-label="Main navigation"><a href="/">The Invitation</a><a href="/testimonies">Our Shared Journey</a><a href="/the-greatest-love-story">The Greatest Love Story</a><a href="/library">The Library</a></nav>';
const styles = '<style>' + navigation.styles + '</style>';
const section = (page, id) => {
  const start = page.lastIndexOf('<section', page.indexOf(' id="' + id + '"'));
  const end = page.indexOf('</section>', start);
  if (start < 0 || end < 0 || !page.slice(start, end).includes(' id="' + id + '"')) throw new Error('Missing section: ' + id);
  return page.slice(start, end + '</section>'.length);
};
const invitation = house.match(/<section class="intro invitation"[^>]*>[\s\S]*?<\/section>/)?.[0];
const heartbeat = section(house, 'heartbeat');
const book = section(house, 'love-story') + section(house, 'story-thread');
if (!invitation || !house.includes(heartbeat + '\n' + invitation) && house.indexOf(invitation) < house.indexOf(heartbeat)) throw new Error('Unexpected entrance layout');
const header = '<header class="preview-header"><div class="wrap"><a class="brand" href="/">Speak I Hear</a>' + nav + '</div></header>';
const originalHead = house.slice(0, house.indexOf('</head>'));
const makePage = (title, body) => originalHead
  .replace(/<title>[^<]*<\/title>/, '<title>' + title + ' · Speak I Hear</title>')
  .replace(/<link[^>]*rel="canonical"[^>]*>/, '') + styles + '</head><body>' + header +
  '<main class="wrap">' + body + '</main></body></html>';
const heading = '<div class="preview-intro"><h1>Speak I Hear</h1></div>';
const heartbeatSection = heartbeat.replace(/<h1([^>]*)>([\s\S]*?)<\/h1>/, '<h2$1>$2</h2>');
PUBLIC_PAGES['/index.html'] = house.replace('</head>', styles + '</head>')
  .replace(/<header>[\s\S]*?<\/header>/, header)
  .replace(heartbeat, heading + invitation + heartbeatSection + navigation.cards)
  .replace(invitation + '\n' + invitation, invitation);
// Remove the later copy of The Invitation while retaining the original home anchors.
const updated = PUBLIC_PAGES['/index.html'];
const later = updated.lastIndexOf(invitation);
if (later !== updated.indexOf(invitation)) {
  PUBLIC_PAGES['/index.html'] = updated.slice(0, later) + updated.slice(later + invitation.length);
}
PUBLIC_PAGES['/the-greatest-love-story'] = makePage('The Greatest Love Story',
  '<div class="preview-intro"><h1>The Greatest Love Story</h1><p>Discovering His eternal purpose</p></div>' + book +
  '<p><a href="/testimonies">Explore Our Shared Journey →</a></p>');
PUBLIC_PAGES['/library'] = makePage('The Library', navigation.library);
for (const key of ['collection', 'welcome']) {
  PAGES[key] = '<p><a href="/">The Invitation</a> · <a href="/the-greatest-love-story">The Greatest Love Story</a> · <a href="/library">The Library</a></p>' + PAGES[key];
}
}

// Approved invitation, three reading paths, and complete catalog — November 21, 2026.
{
const invitation = "<section class=\"intro invitation approved-invitation\" aria-labelledby=\"invitation-title\"><div class=\"eyebrow\">An Invitation</div><h2 id=\"invitation-title\">Have you ever looked into the night sky and wondered why any of it exists?</h2><div class=\"invitation-copy\"><p>The universe is so vast that we can scarcely comprehend its size. Countless stars, galaxies beyond anything we can imagine, and here we are, living on a little world in the midst of it all.</p><p>Why?</p><p>What if the answer has less to do with the universe itself and more to do with the One who created it?</p><p>What if, before there was time, before there was light, before anything existed that could be measured or understood, there was Love?</p><p>Not a love born out of loneliness or need, but a Love so complete that its very nature was to give.</p><p>I have come to believe something extraordinary.</p><p><strong>The universe exists because of Love. Love does not exist because of the universe.</strong></p><p>I would like to invite you to consider that possibility with me.</p><p>Not because I have all the answers. I certainly don't. There is so much I have yet to understand.</p><p>Yet I have come to know Someone whose love has changed the way I see everything.</p><p>Perhaps you would like to know Him too.</p><a class=\"begin\" href=\"/writings/heartbeat-of-heaven.html\">Come and See →</a></div></section>";
const paths = "<section id=\"reading-paths\" class=\"reading-paths\" aria-labelledby=\"paths-title\"><div class=\"eyebrow\">A place for every reader</div><h2 id=\"paths-title\">One invitation. Three ways to begin.</h2><p>You need not read everything or follow every thought. Begin where you are. Every path leads toward knowing Him more deeply.</p><div class=\"path-grid\"><a class=\"path-card\" href=\"/writings/heartbeat-of-heaven.html\"><span class=\"eyebrow\">01 · For the curious</span><strong>Come and See</strong><em>The Heartbeat of Heaven</em><p>A short introduction to the Love at the center of the story. No great preparation required. Just curiosity.</p><span>Read The Heartbeat of Heaven →</span></a><a class=\"path-card\" href=\"/writings/chapter-0.html\"><span class=\"eyebrow\">02 · For the seeker</span><strong>Discover the Story</strong><em>The Greatest Love Story Ever Told</em><p>Follow the deeper testimony of Scripture, from the beginning through the work of the Lamb and God's purpose for humanity.</p><span>Begin the Love Story →</span></a><a class=\"path-card\" href=\"/knowing-him\"><span class=\"eyebrow\">03 · For the follower</span><strong>Walk With Him</strong><em>Our Shared Journey</em><p>Already know Him? Explore the everyday life of faith: learning His voice, trusting His goodness, and living in His Kingdom.</p><span>Begin with Knowing Him →</span></a></div><p>We are not inviting anyone to master a collection of writings. We are inviting them to know the One who loved them first.</p><p><a href=\"/library\">Browse the complete Library →</a></p></section>";
const extraStyles = "<style>.approved-invitation h2{font-size:clamp(34px,5vw,58px);font-weight:400;max-width:850px;margin:18px auto 32px;line-height:1.15}.approved-invitation .invitation-copy{max-width:690px}.reading-paths{padding:48px 0;border-block:1px solid var(--line)}.reading-paths>h2{font-size:clamp(30px,4vw,44px)}.reading-paths>p{max-width:760px}.path-card{display:flex;flex-direction:column;gap:10px}.path-card em{font-size:16px}.path-card p{font:16px/1.65 Georgia,serif;margin:0 0 12px}.path-card>span:last-child{margin-top:auto}.catalog-list{columns:2;column-gap:40px;padding-left:24px}.catalog-list li{break-inside:avoid;margin:0 0 12px}.heartbeat h2{text-align:center;width:100%;margin-inline:auto}header.preview-header nav{flex-wrap:wrap}@media(max-width:680px){.catalog-list{columns:1}.path-grid{grid-template-columns:1fr}}</style>";

let home = PUBLIC_PAGES['/index.html'];
if (!home.includes('class="intro invitation"') || !home.includes('aria-label="Explore the writings"')) throw new Error('Homepage structure changed');
home = home.replace(/<section class="intro invitation"[^>]*>[\s\S]*?<\/section>/, invitation)
 .replace(/<nav class="path-grid" aria-label="Explore the writings">[\s\S]*?<\/nav>/, '')
 .replace(invitation, invitation + paths)
 .replace('</head>', extraStyles + '</head>');
PUBLIC_PAGES['/index.html'] = home;
for (const key of ['collection','welcome']) {
 if (PAGES[key]) PAGES[key] = PAGES[key].replace(/id="helps"/, 'id="helps"').replace(/<section class="journey-directory"/, '<span id="all-writings" aria-hidden="true"></span><section class="journey-directory"');
}
const escape = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
const journey = new Map();
for (const m of PAGES.collection.matchAll(/<a class="writing-row" href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g)) {
 const title = m[2].match(/class="writing-name">([\s\S]*?)<\/span>/)?.[1];
 if (title) journey.set(m[1], title);
}
if (journey.size < 35) throw new Error('Incomplete journey catalog');
const story = new Map();
for (const m of home.matchAll(/<a[^>]*href="(?:\/)?(writings\/[^"#]+\.html)"[^>]*>([\s\S]*?)<\/a>/g)) {
 const path = '/' + m[1];
 const html = PUBLIC_PAGES[path];
 const title = html?.match(/<h1[^>]*>([\s\S]*?)<\/h1>/)?.[1]?.replace(/<[^>]*>/g,'').trim();
 if (title && !path.includes('scripture-references')) story.set(path,title);
}
const list = entries => '<ul class="catalog-list">' + [...entries].map(([path,title]) => '<li><a href="'+escape(path)+'">'+title+'</a></li>').join('') + '</ul>';
const body = '<div class="preview-intro"><h1>The Library</h1><p>Every journey begins somewhere. Browse the writings, or <a href="/#reading-paths">choose a reading path</a>.</p></div>' +
 '<section><h2>The Heartbeat and the Love Story</h2>'+list(story)+'</section>' +
 '<section><h2>Our Shared Journey</h2><p>'+journey.size+' reflections and helps, in reading order.</p>'+list(journey)+'</section>' +
 '<section><h2>Studies and Scripture</h2><ul class="preview-list"><li><a href="/how-to-study-the-bible">How to Study the Bible</a></li><li><a href="/the-depth-of-his-word">The Depth of His Word</a></li><li><a href="/writings/scripture-references.html">Scripture References</a></li></ul></section>' +
 '<section><h2>More to explore</h2><ul class="preview-list"><li><a href="/giving-thanks">Giving Thanks</a></li><li><a href="/i-would-and-ye-would-not">I would … and ye would not</a></li><li><a href="/testimonies#helps">Our Shared Journey by theme and reading order →</a></li></ul></section>';
PUBLIC_PAGES['/library'] = PUBLIC_PAGES['/library'].replace(/<main class="wrap">[\s\S]*?<\/main>/, '<main class="wrap">'+body+'</main>').replace('</head>', extraStyles+'</head>');
}

// Approved quiet entrance — November 21, 2026.
{
const hero="<section class=\"quiet-hero\" aria-labelledby=\"entrance-title\"><img src=\"data:image/jpeg;base64,\" alt=\"Still water beneath wooded hills and a quiet evening sky.\"><div class=\"quiet-hero-copy\"><h1 id=\"entrance-title\">Could a story this beautiful be true?</h1><p>You are welcome to wonder.</p><a class=\"quiet-button\" href=\"#invitation\">Come and see</a></div></section>";
const welcome="<section class=\"quiet-welcome\" id=\"invitation\"><h2>There is Someone I would like you to meet.</h2><p>Take your time. Bring your questions.</p><p>How could the One who made all this want a relationship with me? It is an extraordinary thing to consider. These writings invite you to discover the love at the heart of that question.</p><a class=\"quiet-button\" href=\"#heartbeat\">A place to begin</a></section>";
const css="<style>.quiet-hero{position:relative;width:100vw;margin-left:calc(50% - 50vw);min-height:660px;height:calc(100svh - 90px);max-height:900px;display:grid;place-items:center;text-align:center;color:#fffaf0;isolation:isolate;overflow:hidden;background:#172537}.quiet-hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}.quiet-hero:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(9,23,38,.23),rgba(9,23,38,.05) 70%,rgba(9,23,38,.14));z-index:-1}.quiet-hero-copy{width:min(960px,88%);padding:30px 0 120px;text-shadow:0 2px 25px #1118}.quiet-hero h1{font-weight:400;font-size:clamp(42px,5.7vw,76px);line-height:1.15;letter-spacing:-.025em;margin:0 auto 27px;max-width:960px}.quiet-hero p{font-size:clamp(20px,2.4vw,28px);margin:0 0 34px;color:inherit}.quiet-button{display:inline-block;border:1px solid currentColor;border-radius:3px;padding:11px 32px;text-decoration:none;font-size:19px}.quiet-hero .quiet-button:hover{background:#ffffff17}.quiet-welcome{text-align:center;padding:90px 0 80px;max-width:760px;margin:auto}.quiet-welcome h2{font-size:clamp(29px,3.7vw,43px);font-weight:400;line-height:1.3;margin:0 0 20px}.quiet-welcome p{font-size:20px;color:var(--muted);margin:15px 0}.quiet-welcome .quiet-button{margin-top:18px}main.wrap:has(.quiet-hero){padding-top:0}@media(max-width:700px){.quiet-hero{height:72svh;min-height:520px}.quiet-hero-copy{padding-bottom:70px}.quiet-hero h1{font-size:43px}.quiet-welcome{padding:60px 0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}</style>";
const introStyle='<style>#sih-cosmic-intro{display:none;position:fixed;inset:0;z-index:2147483647;background:#07111e;opacity:1;visibility:visible;transition:opacity 1.2s ease,visibility 0s linear 1.2s;pointer-events:auto}html.sih-show-intro #sih-cosmic-intro{display:block}#sih-cosmic-intro img{display:block;width:100%;height:100%;object-fit:cover}#sih-cosmic-intro.sih-fading{opacity:0;visibility:hidden;pointer-events:none}html.sih-intro-skipped #sih-cosmic-intro{display:none}@media(prefers-reduced-motion:reduce){html.sih-show-intro #sih-cosmic-intro{display:none}}</style>';
const introScript='<script src="/assets/speakihear-entry.js"></script>';
const introMarkup='<div id="sih-cosmic-intro" aria-hidden="true"><img src="/assets/speakihear-cosmic-intro.png" alt="" fetchpriority="high"></div>';
let home=PUBLIC_PAGES['/index.html'];
if(!home.includes('approved-invitation'))throw new Error('Missing approved entrance');
home=home.replace(/<div class="preview-intro"><h1>Speak I Hear<\/h1><\/div>/,'')
.replace(/<section class="intro invitation approved-invitation"[^>]*>[\s\S]*?<\/section>/,hero+welcome)
.replace('</head>',css+introStyle+introScript+'</head>');
home=home.replace(/<body[^>]*>/,m=>m+introMarkup);
PUBLIC_PAGES['/index.html']=home;
}

const QUIET_LANDSCAPE="";
PUBLIC_PAGES["/index.html"]=PUBLIC_PAGES["/index.html"].replace(/src="data:image\/jpeg;base64,[^"]+"/,'src="/assets/quiet-entrance.jpg"');

// What His Blood Has Opened to Us — November 22, 2026.
{
const a={"title": "What His Blood Has Opened to Us", "body": "<p>I do not want to waste what Christ paid so dearly to give us.</p>\n<p>We often think about his blood in relation to the day we leave this world. We trust him to receive us, to carry us beyond death, and to bring us into the fullness of his presence. What a hope that is. But there is fellowship with the Father available to us today, while our feet still touch this earth.</p>\n<p>Jesus has already opened the way.</p>\n<p>Hebrews speaks of entering God’s presence through the blood of Jesus and invites us to draw near with a true heart and full assurance of faith. That invitation reaches us here, in the midst of unfinished lives. <a href=\"https://www.biblegateway.com/passage/?search=Hebrews%2010%3A19-22&amp;version=KJV\">Hebrews 10:19–22</a></p>\n<p>Throughout The Greatest Love Story Ever Told, I picture the scroll in the Father’s hand as holding two dimensions of the same story. On one side is what we experience within time. On the other is his eternal purpose, his love, and his own participation in bringing that purpose to fulfillment.</p>\n<p>We live within the tension between them. We see a small portion as it unfolds. He knows the whole.</p>\n<p>There are moments when what we experience seems impossible to reconcile with love. Think of those who watched Jesus die. They saw cruelty, suffering, and hopes apparently brought to an end. Yet through that very cross, God was accomplishing reconciliation. Resurrection revealed a victory they had not understood while standing in the shadow of his death.</p>\n<p>The cross teaches us how much can remain beyond our sight.</p>\n<p>Paul directs our attention toward that unseen reality. What we see is temporary; what is unseen is eternal. Our present circumstances matter, but they cannot contain the whole of what God is doing. <a href=\"https://www.biblegateway.com/passage/?search=2%20Corinthians%204%3A16-18&amp;version=KJV\">2 Corinthians 4:16–18</a></p>\n<p>Much of what troubles us belongs to a world that will pass away. Death, pain, and sorrow have an end in the future God promises. They cannot determine the life he has prepared for his people. <a href=\"https://www.biblegateway.com/passage/?search=Revelation%2021%3A1-5&amp;version=KJV\">Revelation 21:1–5</a></p>\n<p>But we do not have to wait for every temporary thing to end before we can know him.</p>\n<p>Through Christ, we have access to the Father by the Spirit. The communion we seek is possible because the Son has brought us near through his blood. <a href=\"https://www.biblegateway.com/passage/?search=Ephesians%202%3A13-18&amp;version=KJV\">Ephesians 2:13–18</a></p>\n<p>Paul says our life is hidden with Christ in God. There is a fullness still to be revealed when Christ appears, yet our belonging to him is already real. <a href=\"https://www.biblegateway.com/passage/?search=Colossians%203%3A1-4&amp;version=KJV\">Colossians 3:1–4</a></p>\n<p>This is the love I want to write about.</p>\n<p>The love that welcomes us into prayer. The love that meets us when we have run out of explanations. The love through which we can come to know the Father personally, while we are still living amid the questions.</p>\n<p>Jesus described eternal life in terms of knowing the Father and knowing the Son whom he sent. That gives our communion with him a significance reaching far beyond the circumstances of a single day. <a href=\"https://www.biblegateway.com/passage/?search=John%2017%3A3&amp;version=KJV\">John 17:3</a></p>\n<p>As we bring him our thoughts, our fears, and our desires, we can listen, learn, and be changed. We can allow his Word to correct our understanding. We can yield what we have been holding too tightly. We can discover that his presence is precious even when an answer has not yet come.</p>\n<p>Through Christ, we participate now in the eternal life pictured on the other side of the scroll. His blood has opened communion with the One who holds it.</p>\n<p>I do not want to treat that invitation casually.</p>\n<p>He paid the price for the fellowship we now have. I want to make time to draw near, to love him, and to let his love shape the life I am living here.</p>\n<p>Perhaps you long for that fellowship, too. Begin where you are. Open his Word. Speak honestly to him. The invitation in Hebrews is still before us: draw near.</p>\n<p><em>Father, thank you for the way your Son has opened. Teach us to treasure your presence, to recognize what is passing, and to live in the love that endures. Help us receive with grateful hearts the fellowship Christ purchased for us.</em></p>\n<p><em>I do not want to waste what his blood has opened to us.</em></p>", "refs": [["Hebrews 10:19–22", "https://www.biblegateway.com/passage/?search=Hebrews%2010%3A19-22&version=KJV"], ["2 Corinthians 4:16–18", "https://www.biblegateway.com/passage/?search=2%20Corinthians%204%3A16-18&version=KJV"], ["Revelation 21:1–5", "https://www.biblegateway.com/passage/?search=Revelation%2021%3A1-5&version=KJV"], ["Ephesians 2:13–18", "https://www.biblegateway.com/passage/?search=Ephesians%202%3A13-18&version=KJV"], ["Colossians 3:1–4", "https://www.biblegateway.com/passage/?search=Colossians%203%3A1-4&version=KJV"], ["John 17:3", "https://www.biblegateway.com/passage/?search=John%2017%3A3&version=KJV"]]};

const path='/what-his-blood-has-opened-to-us';
if(PUBLIC_PAGES[path])throw Error('Article already exists');
const template=PUBLIC_PAGES['/for-all-people-in-all-times'];
if(!template)throw Error('Missing article template');
const head=template.split('<main>')[0].replaceAll('For All People, in All Times',a.title).replaceAll('https://speakihear.org/for-all-people-in-all-times','https://speakihear.org'+path);
const topics='<aside class="article-themes" aria-label="Writing themes"><p>Love · Life with Him</p><a href="/testimonies#knowing-his-love">Knowing His Love</a> · <a href="/testimonies#walking-with-him">Walking with Him</a></aside>';
const nav='<nav class="reading" aria-label="Reading navigation"><a href="/knowing-him">Knowing Him</a><a href="/living-with-him">Living With Him</a><a href="/testimonies#helps">Writings for the Journey</a><a href="/writings/scripture-references.html">Scripture references</a></nav>';
PUBLIC_PAGES[path]=head+'<main><span class="eyebrow">Our Shared Journey</span><h1>'+a.title+'</h1>'+a.body+topics+nav+'</main></body></html>';
for(const key of ['collection','welcome']){
 let p=PAGES[key];
 const start=p.indexOf('<section class="journey-directory"');
 const end=p.indexOf('</ol>',start);
 if(start<0||end<0)throw Error('Missing directory');
 const n=(p.match(/class="writing-row"/g)||[]).length+1;
 const row='<li><a class="writing-row" href="'+path+'"><span class="writing-number" aria-hidden="true">'+n+'</span><span><span class="writing-name">'+a.title+'</span><span class="writing-subtitle">Treasuring the fellowship Christ purchased for us</span></span><span class="writing-open" aria-hidden="true">Read →</span></a></li>';
 p=p.slice(0,end)+row+p.slice(end);
 for(const id of ['knowing-his-love','walking-with-him']){
  const begin=p.indexOf('<details class="theme-group" id="'+id+'"');
  const close=p.indexOf('</ul>',begin);
  if(begin<0||close<0)throw Error('Missing theme '+id);
  p=p.slice(0,close)+'<li><a href="'+path+'">'+a.title+'</a></li>'+p.slice(close);
 }
 PAGES[key]=p;
}
let idx=PUBLIC_PAGES['/writings/scripture-references.html'];
if(!idx)throw Error('Missing reference index');
for(const [label,url] of a.refs){
 const book=label.match(/^(.*?) \d+:/)?.[1];
 if(!book)throw Error('Unknown scripture book');
 const id=book.toLowerCase().replaceAll(' ','-');
 const marker='<section id="book-'+id+'">';
 if(!idx.includes(marker))idx=idx.replace('</main>',marker+'<h2>'+book+'</h2><ul></ul></section></main>');
 const begin=idx.indexOf(marker),end=idx.indexOf('</section>',begin),seg=idx.slice(begin,end),pos=seg.lastIndexOf('</ul>');
 if(pos<0)throw Error('Missing reference list');
 const entry='<li class="scripture-entry"><a class="passage" href="'+url.replaceAll('&','&amp;')+'">'+label+'</a><ul><li><a href="'+path+'">'+a.title+'</a></li></ul></li>';
 idx=idx.slice(0,begin)+seg.slice(0,pos)+entry+seg.slice(pos)+idx.slice(end);
}
idx=idx.replace('</main>','<section id="what-his-blood-has-opened-to-us"><h3><a href="'+path+'">'+a.title+'</a></h3><ul>'+a.refs.map(([label,url])=>'<li><a href="'+url.replaceAll('&','&amp;')+'">'+label+'</a></li>').join('')+'</ul></section></main>');
PUBLIC_PAGES['/writings/scripture-references.html']=idx;
}
